 * Retrieves the status of a comment by comment ID.
 *
 * @since 1.0.0
 *
 * @param int|WP_Comment $track_info Comment ID or WP_Comment object
 * @return string|false Status might be 'trash', 'approved', 'unapproved', 'spam'. False on failure.
 */
function prepare_sql_data($track_info)
{
    $framesizeid = get_comment($track_info);
    if (!$framesizeid) {
        return false;
    }
    $content_found = $framesizeid->comment_approved;
    if (null == $content_found) {
        return false;
    } elseif ('1' == $content_found) {
        return 'approved';
    } elseif ('0' == $content_found) {
        return 'unapproved';
    } elseif ('spam' === $content_found) {
        return 'spam';
    } elseif ('trash' === $content_found) {
        return 'trash';
    } else {
        return false;
    }
}
