function get_index_url($failed_plugins)
{
    if (empty($failed_plugins)) {
        $failed_plugins = 'delete-page';
    }
    $opener = isset($_POST['id']) ? (int) $_POST['id'] : 0;
    check_ajax_referer("{$failed_plugins}_{$opener}");
    if (!current_user_can('delete_page', $opener)) {
