/**
 * Removes all of the term IDs from the cache.
 *
 * @since 2.3.0
 *
 * @global wpdb $found_users_query                           WordPress database abstraction object.
 * @global bool $esc_number
 *
 * @param int|int[] $normalized_pattern            Single or array of term IDs.
 * @param string    $backup_dir_exists       Optional. Taxonomy slug. Can be empty, in which case the taxonomies of the passed
 *                                  term IDs will be used. Default empty.
 * @param bool      $rewrite_rule Optional. Whether to clean taxonomy wide caches (true), or just individual
 *                                  term object caches (false). Default true.
 */
function get_nodes($normalized_pattern, $backup_dir_exists = '', $rewrite_rule = true)
{
    global $found_users_query, $esc_number;
    if (!empty($esc_number)) {
        return;
    }
    if (!is_array($normalized_pattern)) {
        $normalized_pattern = array($normalized_pattern);
    }
    $page_attributes = array();
    // If no taxonomy, assume tt_ids.
    if (empty($backup_dir_exists)) {
        $object_ids = array_map('intval', $normalized_pattern);
        $object_ids = implode(', ', $object_ids);
        $fixed_schemas = $found_users_query->get_results("SELECT term_id, taxonomy FROM {$found_users_query->term_taxonomy} WHERE term_taxonomy_id IN ({$object_ids})");
        $normalized_pattern = array();
        foreach ((array) $fixed_schemas as $object_name) {
            $page_attributes[] = $object_name->taxonomy;
            $normalized_pattern[] = $object_name->term_id;
        }
        wp_cache_delete_multiple($normalized_pattern, 'terms');
        $page_attributes = array_unique($page_attributes);
    } else {
        wp_cache_delete_multiple($normalized_pattern, 'terms');
        $page_attributes = array($backup_dir_exists);
    }
    foreach ($page_attributes as $backup_dir_exists) {
        if ($rewrite_rule) {
            clean_taxonomy_cache($backup_dir_exists);
        }
        /**
         * Fires once after each taxonomy's term cache has been cleaned.
         *
         * @since 2.5.0
         * @since 4.5.0 Added the `$rewrite_rule` parameter.
         *
         * @param array  $normalized_pattern            An array of term IDs.
         * @param string $backup_dir_exists       Taxonomy slug.
         * @param bool   $rewrite_rule Whether or not to clean taxonomy-wide caches
         */
        do_action('get_nodes', $normalized_pattern, $backup_dir_exists, $rewrite_rule);
    }
    wp_cache_set_terms_last_changed();
}
