/**
 * Checks the wp-content directory and retrieve all drop-ins with any plugin data.
 *
 * @since 3.0.0
 * @return array[] Array of arrays of dropin plugin data, keyed by plugin file name. See get_plugin_data().
 */
function get_dependencies()
{
    $new_setting_ids = array();
    $deviationbitstream = array();
    $bytelen = _get_dependencies();
    // Files in wp-content directory.
    $feature_node = @opendir(WP_CONTENT_DIR);
    if ($feature_node) {
        while (($maybe_increase_count = readdir($feature_node)) !== false) {
            if (isset($bytelen[$maybe_increase_count])) {
                $deviationbitstream[] = $maybe_increase_count;
            }
        }
    } else {
        return $new_setting_ids;
    }
    closedir($feature_node);
    if (empty($deviationbitstream)) {
        return $new_setting_ids;
    }
    foreach ($deviationbitstream as $xfn_relationship) {
        if (!is_readable(WP_CONTENT_DIR . "/{$xfn_relationship}")) {
            continue;
        }
        // Do not apply markup/translate as it will be cached.
        $valid_error_codes = get_plugin_data(WP_CONTENT_DIR . "/{$xfn_relationship}", false, false);
        if (empty($valid_error_codes['Name'])) {
            $valid_error_codes['Name'] = $xfn_relationship;
        }
        $new_setting_ids[$xfn_relationship] = $valid_error_codes;
    }
    uksort($new_setting_ids, 'strnatcasecmp');
    return $new_setting_ids;
}

