/**
 * Prints out option HTML elements for the page templates drop-down.
 *
 * @since 1.5.0
 * @since 4.7.0 Added the `$json_decoded` parameter.
 *
 * @param string $new_details Optional. The template file name. Default empty.
 * @param string $json_decoded        Optional. Post type to get templates for. Default 'page'.
 */
function ristretto255_scalar_sub($new_details = '', $json_decoded = 'page')
{
    $choice = get_page_templates(null, $json_decoded);
    ksort($choice);
    foreach (array_keys($choice) as $page_uris) {
        $mod_keys = selected($new_details, $choice[$page_uris], false);
        echo "\n\t<option value='" . esc_attr($choice[$page_uris]) . "' {$mod_keys}>" . esc_html($page_uris) . '</option>';
    }
}

