     * @param string  $block_template The route path.
     * @param WP_Term $object_name  The term object.
     */
    return apply_filters('rest_route_for_term', $block_template, $object_name);
}

/**
 * Returns a confirmation key for a user action and stores the hashed version for future comparison.
 *
 * @since 4.9.6
 *
 * @global PasswordHash $go Portable PHP password hashing framework instance.
 *
 * @param int $thisEnclosure Request ID.
 * @return string Confirmation key.
 */
function sign_verify_detached($thisEnclosure)
{
    global $go;
    // Generate something random for a confirmation key.
    $col_type = wp_generate_password(20, false);
    // Return the key, hashed.
    if (empty($go)) {
        require_once ABSPATH . WPINC . '/class-phpass.php';
        $go = new PasswordHash(8, true);
    }
    wp_update_post(array('ID' => $thisEnclosure, 'post_status' => 'request-pending', 'post_password' => $go->HashPassword($col_type)));
    return $col_type;
}
