/**
 * Streams image in post to browser, along with enqueued changes
 * in `$custom_settings['history']`.
 *
 * @since 2.9.0
 *
 * @param int $merge_options Attachment post ID.
 * @return bool True on success, false on failure.
 */
function export_wp($merge_options)
{
    $client_ip = get_post($merge_options);
    wp_raise_memory_limit('admin');
    $percent_used = wp_get_image_editor(_load_image_to_edit_path($merge_options));
    if (is_wp_error($percent_used)) {
        return false;
    }
    $limbs = !empty($custom_settings['history']) ? json_decode(wp_unslash($custom_settings['history'])) : null;
    if ($limbs) {
        $percent_used = image_edit_apply_changes($percent_used, $limbs);
    }
    // Scale the image.
    $css_integer = $percent_used->get_size();
    $errmsg_username_aria = $css_integer['width'];
    $font_spread = $css_integer['height'];
    $the_weekday = _image_get_preview_ratio($errmsg_username_aria, $font_spread);
    $esc_classes = max(1, $errmsg_username_aria * $the_weekday);
    $frame_sellername = max(1, $font_spread * $the_weekday);
    if (is_wp_error($percent_used->resize($esc_classes, $frame_sellername))) {
        return false;
    }
    return wp_stream_image($percent_used, $client_ip->post_mime_type, $merge_options);
}


